DECLARE
  PROCEDURE check_row(p_row NUMBER, p_expected VARCHAR2) IS
    v_actual VARCHAR2(64);
  BEGIN
    SELECT LOWER(RAWTOHEX(STANDARD_HASH(
        TO_CHAR(NVL(LENGTHB(AlbumId), 0), 'FM999999990') || ':' || AlbumId ||
        TO_CHAR(NVL(LENGTHB(Title), 0), 'FM999999990') || ':' || Title ||
        TO_CHAR(NVL(LENGTHB(ArtistId), 0), 'FM999999990') || ':' || ArtistId, 'SHA256')))
      INTO v_actual FROM STG_ALBUM WHERE CSV_ROW_NUMBER = p_row;
    IF v_actual <> p_expected OR v_actual IS NULL THEN
      RAISE_APPLICATION_ERROR(-20007, 'Contenido distinto: STG_ALBUM, registro ' || p_row);
    END IF;
  END;
