DECLARE
  PROCEDURE check_row(p_row NUMBER, p_expected VARCHAR2) IS
    v_actual VARCHAR2(64);
  BEGIN
    SELECT LOWER(RAWTOHEX(STANDARD_HASH(
        TO_CHAR(NVL(LENGTHB(InvoiceId), 0), 'FM999999990') || ':' || InvoiceId ||
        TO_CHAR(NVL(LENGTHB(CustomerId), 0), 'FM999999990') || ':' || CustomerId ||
        TO_CHAR(NVL(LENGTHB(InvoiceDate), 0), 'FM999999990') || ':' || InvoiceDate ||
        TO_CHAR(NVL(LENGTHB(BillingAddress), 0), 'FM999999990') || ':' || BillingAddress ||
        TO_CHAR(NVL(LENGTHB(BillingCity), 0), 'FM999999990') || ':' || BillingCity ||
        TO_CHAR(NVL(LENGTHB(BillingState), 0), 'FM999999990') || ':' || BillingState ||
        TO_CHAR(NVL(LENGTHB(BillingCountry), 0), 'FM999999990') || ':' || BillingCountry ||
        TO_CHAR(NVL(LENGTHB(BillingPostalCode), 0), 'FM999999990') || ':' || BillingPostalCode ||
        TO_CHAR(NVL(LENGTHB(Total), 0), 'FM999999990') || ':' || Total, 'SHA256')))
      INTO v_actual FROM STG_INVOICE WHERE CSV_ROW_NUMBER = p_row;
    IF v_actual <> p_expected OR v_actual IS NULL THEN
      RAISE_APPLICATION_ERROR(-20007, 'Contenido distinto: STG_INVOICE, registro ' || p_row);
    END IF;
  END;
BEGIN
  check_row(401, '0263efc576a2c8c5500f0f012447a3da4420493802d2a55177a76f491c8d93d8');
  check_row(402, '6296a99cbcfeb118fd814cf20d4f59263ef7fdcd79506d386b975f5774ddc878');
