DECLARE
  PROCEDURE check_row(p_row NUMBER, p_expected VARCHAR2) IS
    v_actual VARCHAR2(64);
  BEGIN
    SELECT LOWER(RAWTOHEX(STANDARD_HASH(
        TO_CHAR(NVL(LENGTHB(TrackId), 0), 'FM999999990') || ':' || TrackId ||
        TO_CHAR(NVL(LENGTHB(Name), 0), 'FM999999990') || ':' || Name ||
        TO_CHAR(NVL(LENGTHB(AlbumId), 0), 'FM999999990') || ':' || AlbumId ||
        TO_CHAR(NVL(LENGTHB(MediaTypeId), 0), 'FM999999990') || ':' || MediaTypeId ||
        TO_CHAR(NVL(LENGTHB(GenreId), 0), 'FM999999990') || ':' || GenreId ||
        TO_CHAR(NVL(LENGTHB(Composer), 0), 'FM999999990') || ':' || Composer ||
        TO_CHAR(NVL(LENGTHB(Milliseconds), 0), 'FM999999990') || ':' || Milliseconds ||
        TO_CHAR(NVL(LENGTHB(Bytes), 0), 'FM999999990') || ':' || Bytes ||
        TO_CHAR(NVL(LENGTHB(UnitPrice), 0), 'FM999999990') || ':' || UnitPrice, 'SHA256')))
      INTO v_actual FROM STG_TRACK WHERE CSV_ROW_NUMBER = p_row;
    IF v_actual <> p_expected OR v_actual IS NULL THEN
      RAISE_APPLICATION_ERROR(-20007, 'Contenido distinto: STG_TRACK, registro ' || p_row);
    END IF;
  END;
